def amicable_numbers_sum(n):
    def sum_proper_divisors(x):
        if x < 2:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                j = x // i
                if j != i:
                    total += j
            i += 1
        return total

    result = 0
    for num in range(2, n + 1):
        partner = sum_proper_divisors(num)
        if partner != num and sum_proper_divisors(partner) == num:
            result += num
    return result
```

