def reverse_vowels(s: str) -> str:
    vowels = set("aeiouAEIOU")
    chars = list(s)
    vowel_indices = [i for i, ch in enumerate(chars) if ch in vowels]
    vowel_values = [chars[i] for i in vowel_indices]

    for i, value in zip(vowel_indices, reversed(vowel_values)):
        chars[i] = value

    return "".join(chars)
