def sumofFactors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            complement = n // i
            if complement != i and complement % 2 == 0:
                total += complement
        i += 1
    return total
