def last_Digit_Factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    # For n >= 5, n! contains both 2 and 5 as factors,
    # so it is divisible by 10 and its last digit is 0.
    if n >= 5:
        return 0
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result % 10
```

